import { PHONE_INPUT_MAX_LENGTH } from '@prime-crm/shared';
import { IsString, IsUUID, MaxLength } from 'class-validator';
import { IsPhone } from '../../../common/validators/is-phone.validator';

/** `POST /owners/:id/calls` (mirrors StartCallRequestSchema). */
export class StartCallDto {
  /** One of the owner's numbers, typed any way. */
  @IsString()
  @MaxLength(PHONE_INPUT_MAX_LENGTH)
  @IsPhone()
  phone!: string;

  /** Generated by the client per tap: a repeat returns the same call. */
  @IsUUID()
  clientRequestId!: string;
}
